// O ponto de interrogação torna o parâmetro dispensável na chamada
function saudar(nome: string, titulo?: string): string {
  // aqui dentro, titulo é string | undefined
  if (titulo === undefined) {
    return `Olá, ${nome}`;
  }
  return `Olá, ${titulo} ${nome}`;
}

console.log(saudar("Ana")); // "Olá, Ana"
console.log(saudar("Ana", "Dra.")); // "Olá, Dra. Ana"
console.log(saudar("Ana", undefined)); // "Olá, Ana"

// Usar o valor sem verificar é exatamente o que o compilador impede
function emMaiusculas(titulo?: string): string {
  // @ts-expect-error titulo é string | undefined e undefined não tem toUpperCase
  return titulo.toUpperCase();
}

// @ts-expect-error um parâmetro obrigatório não pode vir depois de um opcional
function ordemErrada(titulo?: string, nome: string): string {
  return `${titulo} ${nome}`;
}

console.log(emMaiusculas("dra."), ordemErrada("dra.", "Ana"));

// O tipo vem do valor por omissão: vezes é number, sem anotação nenhuma
function repetir(texto: string, vezes = 2): string {
  return texto.repeat(vezes);
}

console.log(repetir("ab")); // "abab"
console.log(repetir("ab", 3)); // "ababab"
console.log(repetir("ab", undefined)); // "abab"

// @ts-expect-error o tipo inferido a partir de 2 é number
console.log(repetir("ab", "3"));

// A inferência alarga o literal: lado fica string, e não "esquerda"
function alinhar(texto: string, lado = "esquerda"): string {
  return `${lado}:${texto}`;
}
console.log(alinhar("oi", "direita")); // "direita:oi"
console.log(alinhar("oi", "qualquer coisa")); // nada o impede

// Para restringir, anote: a anotação e o valor por omissão convivem
function alinharEstrito(
  texto: string,
  lado: "esquerda" | "direita" = "esquerda",
): string {
  return `${lado}:${texto}`;
}
console.log(alinharEstrito("oi")); // "esquerda:oi"
// @ts-expect-error "centro" não pertence à união anotada
console.log(alinharEstrito("oi", "centro"));

// A anotação também é precisa quando o valor por omissão é vago
function juntar(partes: string[] = [], ligacao = "-"): string {
  return partes.join(ligacao);
}
console.log(juntar(["a", "b"])); // "a-b"

function comInterrogacao(valor?: number): number {
  // valor: number | undefined, tem de ser tratado
  return (valor ?? 0) * 2;
}

function comOmissao(valor = 0): number {
  // valor: number, já não pode ser undefined
  return valor * 2;
}

// Vistas de fora, as duas assinaturas são iguais: (valor?: number) => number
console.log(comInterrogacao(), comInterrogacao(undefined), comInterrogacao(5)); // 0 0 10
console.log(comOmissao(), comOmissao(undefined), comOmissao(5)); // 0 0 10

// A diferença está dentro do corpo
function triplo(valor?: number): number {
  // @ts-expect-error valor pode ser undefined e undefined não se multiplica
  return valor * 3;
}
function triploSeguro(valor = 1): number {
  return valor * 3; // nenhuma verificação é necessária
}
console.log(triplo(2), triploSeguro());

// @ts-expect-error os dois mecanismos excluem-se: ou ? ou valor por omissão
function ambos(valor?: number = 0): number {
  return valor;
}
console.log(ambos());

// Permitido: o valor por omissão vem antes de um parâmetro obrigatório
function rotular(separador = " - ", texto: string): string {
  return `${separador}${texto}`;
}

// Mas a posição continua a ser obrigatória: são sempre dois argumentos
// @ts-expect-error esperava 2 argumentos e só recebeu 1
console.log(rotular("olá"));

// A única forma de aproveitar o valor por omissão é passar undefined à mão
console.log(rotular(undefined, "olá")); // " - olá"
console.log(rotular(" | ", "olá")); // " | olá"

// A versão que se deve escrever: opcionais e com valor por omissão no fim
function rotularBem(texto: string, separador = " - "): string {
  return `${separador}${texto}`;
}
console.log(rotularBem("olá")); // " - olá"

// O rest recolhe o que sobrar; o tipo é o do array, não o do elemento
function somar(...valores: number[]): number {
  return valores.reduce((total, valor) => total + valor, 0);
}
console.log(somar()); // 0
console.log(somar(1, 2, 3)); // 6

// Pode vir depois de parâmetros normais, desde que fique em último
function registar(nivel: string, ...mensagens: string[]): string {
  return `[${nivel}] ${mensagens.join(" | ")}`;
}
console.log(registar("info", "arrancou", "pronto")); // "[info] arrancou | pronto"

// Espalhar um array na chamada funciona porque o rest aceita qualquer número
const medidas: number[] = [1, 2, 3, 4];
console.log(somar(...medidas)); // 10

// @ts-expect-error o rest tem de ser o último parâmetro da lista
function depoisDoRest(...partes: string[], fim: string): string {
  return `${partes.join("")}${fim}`;
}

// @ts-expect-error o tipo de um rest tem de ser um array ou uma tupla
function restEscalar(...partes: string): string {
  return partes;
}

type Cor = "vermelho" | "verde" | "azul";

// Rest tipado com tupla: número, ordem e tipos fixos, com nomes nas sugestões
function desenhar(...args: [x: number, y: number, cor: Cor]): string {
  const [x, y, cor] = args;
  return `(${x}, ${y}) em ${cor}`;
}
console.log(desenhar(10, 20, "azul")); // "(10, 20) em azul"

// @ts-expect-error a tupla exige exatamente três argumentos
desenhar(10, 20);

// @ts-expect-error a terceira posição só aceita os literais de Cor
desenhar(10, 20, "roxo");

// Espalhar uma tupla na chamada encaixa posição a posição
const ponto: [number, number, Cor] = [1, 2, "verde"];
console.log(desenhar(...ponto)); // "(1, 2) em verde"

// A tupla também admite opcionais e um rest final
function mover(...args: [x: number, y: number, z?: number]): number {
  const [x, y, z = 0] = args;
  return x + y + z;
}
console.log(mover(1, 2), mover(1, 2, 3)); // 3 6

function notificar(
  ...args: [assunto: string, primeiro: string, ...outros: string[]]
): string {
  const [assunto, ...destinatarios] = args;
  return `${assunto} -> ${destinatarios.join(", ")}`;
}
console.log(notificar("Reunião", "ana@ex.pt")); // "Reunião -> ana@ex.pt"

// O tipo anota-se depois do padrão inteiro, nunca dentro dele
function apresentar({ nome, idade }: { nome: string; idade: number }): string {
  return `${nome} tem ${idade}`;
}
console.log(apresentar({ nome: "Ana", idade: 30 })); // "Ana tem 30"

// @ts-expect-error isto renomeia nome para string e deixa-o com tipo implícito
function enganosa({ nome: string }) {
  return string;
}

interface Opcoes {
  readonly recursivo?: boolean;
  readonly profundidade?: number;
  readonly ignorar?: readonly string[];
}

// O padrão mais usado na prática: valores por omissão dentro do destructuring
// e um = {} no fim, para o próprio objeto poder ser omitido
function percorrer(
  raiz: string,
  { recursivo = true, profundidade = 3, ignorar = [] }: Opcoes = {},
): string {
  return `${raiz} ${recursivo} ${profundidade} ${ignorar.length}`;
}

console.log(percorrer("/src")); // "/src true 3 0"
console.log(percorrer("/src", { profundidade: 1 })); // "/src true 1 0"
console.log(percorrer("/src", { ignorar: ["dist"] })); // "/src true 3 1"

console.log(enganosa({ nome: "Ana" }));

