function etiquetaOpcional(texto: string, prefixo?: string): string {
  if (prefixo === undefined) {
    return texto;
  }
  return `${prefixo}${texto}`;
}

function etiquetaPorOmissao(texto: string, prefixo = "#"): string {
  return `${prefixo}${texto}`;
}

console.log(etiquetaOpcional("typescript")); // "typescript"
console.log(etiquetaOpcional("typescript", "@")); // "@typescript"
console.log(etiquetaPorOmissao("typescript")); // "#typescript"
console.log(etiquetaPorOmissao("typescript", undefined)); // "#typescript"

function maiorDe(...valores: number[]): number | undefined {
  if (valores.length === 0) {
    return undefined;
  }
  return valores.reduce((maior, valor) => (valor > maior ? valor : maior));
}

function juntarCaminho(base: string, ...partes: string[]): string {
  if (partes.length === 0) {
    return base;
  }
  return `${base}/${partes.join("/")}`;
}

console.log(maiorDe(3, 9, 4)); // 9
console.log(maiorDe()); // undefined

const extras: number[] = [12, 7];
console.log(maiorDe(...extras)); // 12

console.log(juntarCaminho("/src")); // "/src"
console.log(juntarCaminho("/src", "app", "main.ts")); // "/src/app/main.ts"

interface OpcoesFormato {
  readonly maiusculas?: boolean;
  readonly largura?: number;
  readonly preenchimento?: string;
}

function formatar(
  texto: string,
  {
    maiusculas = false,
    largura = 10,
    preenchimento = ".",
  }: OpcoesFormato = {},
): string {
  const base = maiusculas ? texto.toUpperCase() : texto;
  return base.padEnd(largura, preenchimento);
}

console.log(formatar("ola")); // "ola......."
console.log(formatar("ola", { maiusculas: true })); // "OLA......."
console.log(formatar("ola", { largura: 5, preenchimento: "-" })); // "ola--"
console.log(formatar("ola", { largura: 2 })); // "ola"

type Nivel = "info" | "aviso" | "erro";

function registarEvento(
  ...args: [nivel: Nivel, mensagem: string, ...detalhes: string[]]
): string {
  const [nivel, mensagem, ...detalhes] = args;
  const cauda = detalhes.length > 0 ? ` (${detalhes.join("; ")})` : "";
  return `[${nivel.toUpperCase()}] ${mensagem}${cauda}`;
}

function formatarData(
  ...args: [dia: number, mes: number, ano?: number]
): string {
  const [dia, mes, ano = 2026] = args;
  const dd = String(dia).padStart(2, "0");
  const mm = String(mes).padStart(2, "0");
  return `${dd}/${mm}/${ano}`;
}

console.log(registarEvento("info", "arrancou")); // "[INFO] arrancou"
console.log(registarEvento("erro", "falhou", "código 500", "a repetir"));
// "[ERRO] falhou (código 500; a repetir)"

// @ts-expect-error a tupla exige pelo menos o nível e a mensagem
registarEvento("aviso");

// @ts-expect-error "debug" não pertence ao tipo Nivel
registarEvento("debug", "teste");

console.log(formatarData(3, 7)); // "03/07/2026"
console.log(formatarData(3, 7, 1999)); // "03/07/1999"

const entrada: [Nivel, string, string] = ["aviso", "disco cheio", "95%"];
console.log(registarEvento(...entrada)); // "[AVISO] disco cheio (95%)"
